package com.example.indoorar

import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.view.View
import android.widget.*
import androidx.activity.result.contract.ActivityResultContracts
import com.bumptech.glide.Glide
import com.google.android.material.button.MaterialButton
import com.google.android.material.textfield.TextInputEditText
import com.google.firebase.Timestamp
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.storage.FirebaseStorage

class ActivityCadastrarMapa : BaseActivity() {

    private lateinit var imgPreview: ImageView
    private lateinit var txtHintImagem: TextView
    private lateinit var editNome: TextInputEditText
    private lateinit var editDescricao: TextInputEditText
    private lateinit var dropTipoLocal: AutoCompleteTextView
    private lateinit var editAndar: TextInputEditText
    private lateinit var editHorario: TextInputEditText
    private lateinit var btnSalvar: MaterialButton
    private lateinit var progressSalvar: ProgressBar

    private var selectedImageUri: Uri? = null

    private val pickImage = registerForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
        uri?.let {
            selectedImageUri = it
            txtHintImagem.visibility = View.GONE
            Glide.with(this).load(it).centerCrop().into(imgPreview)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_cadastrar_mapa)

        // Views
        imgPreview = findViewById(R.id.imgPreview)
        txtHintImagem = findViewById(R.id.txtHintImagem)
        editNome = findViewById(R.id.editNome)
        editDescricao = findViewById(R.id.editDescricao)
        dropTipoLocal = findViewById(R.id.dropTipoLocal)
        editAndar = findViewById(R.id.editAndar)
        editHorario = findViewById(R.id.editHorario)
        btnSalvar = findViewById(R.id.btnSalvar)
        progressSalvar = findViewById(R.id.progressSalvar)

        // Voltar
        findViewById<ImageView>(R.id.btnVoltar).setOnClickListener { onBackPressedDispatcher.onBackPressed() }

        // Dropdown tipos
        val tipos = resources.getStringArray(R.array.tipos_locais)
        val adapter = ArrayAdapter(this, android.R.layout.simple_list_item_1, tipos)
        dropTipoLocal.setAdapter(adapter)

        // Escolher imagem
        findViewById<View>(R.id.cardImagem).setOnClickListener { pickImage.launch("image/*") }
        imgPreview.setOnClickListener { pickImage.launch("image/*") }

        // Salvar
        btnSalvar.setOnClickListener { salvarMapa() }
    }

    private fun setLoading(loading: Boolean) {
        progressSalvar.visibility = if (loading) View.VISIBLE else View.GONE
        btnSalvar.isEnabled = !loading
    }

    private fun salvarMapa() {
        val nome = editNome.text?.toString()?.trim().orEmpty()
        val descricao = editDescricao.text?.toString()?.trim().orEmpty()
        val tipo = dropTipoLocal.text?.toString()?.trim().orEmpty()
        val andar = editAndar.text?.toString()?.trim().orEmpty()
        val horario = editHorario.text?.toString()?.trim().orEmpty()

        // Chips
        val recursos = mutableListOf<String>()
        if (findViewById<CompoundButton>(R.id.chipAcessivel).isChecked) recursos += "Acessível"
        if (findViewById<CompoundButton>(R.id.chipElevador).isChecked) recursos += "Elevador"
        if (findViewById<CompoundButton>(R.id.chipEscadas).isChecked) recursos += "Escadas"
        if (findViewById<CompoundButton>(R.id.chipBanheiros).isChecked) recursos += "Banheiros"
        if (findViewById<CompoundButton>(R.id.chipWifi).isChecked) recursos += "Wi-Fi"
        if (findViewById<CompoundButton>(R.id.chipEstacionamento).isChecked) recursos += "Estacionamento"

        if (nome.isEmpty()) { showSnackbar("Informe o nome do mapa"); return }
        if (descricao.isEmpty()) { showSnackbar("Informe a descrição"); return }
        if (tipo.isEmpty()) { showSnackbar("Selecione o tipo do local"); return }

        val user = FirebaseAuth.getInstance().currentUser
        if (user == null) {
            showSnackbar("Você precisa estar logado para cadastrar um mapa")
            return
        }

        setLoading(true)

        fun returnToCaller(mapId: String) {
            val data = Intent().apply { putExtra("MAP_ID", mapId) }
            setResult(RESULT_OK, data)
            finish()
        }

        fun saveToFirestore(imageUrl: String?) {
            val dados = hashMapOf(
                "nome" to nome,
                "descricao" to descricao,
                "tipo" to tipo,
                "andar" to andar,
                "horario" to horario,
                "recursos" to recursos,
                "imagemUrl" to (imageUrl ?: ""),
                // campos compatíveis com fluxo maker
                "criadorUid" to user.uid,
                "nomeAutor" to (user.displayName ?: ""),
                "dataCriacao" to Timestamp.now()
            )
            FirebaseFirestore.getInstance().collection("mapas")
                .add(dados)
                .addOnSuccessListener { docRef ->
                    showSnackbar("Mapa cadastrado com sucesso.")
                    setLoading(false)
                    returnToCaller(docRef.id)
                }
                .addOnFailureListener { e ->
                    showSnackbar("Erro ao salvar: ${e.message}")
                    setLoading(false)
                }
        }

        val uri = selectedImageUri
        if (uri == null) {
            saveToFirestore(null)
        } else {
            val storage = FirebaseStorage.getInstance().reference
                .child("map_images/${user.uid}/${System.currentTimeMillis()}.jpg")
            try {
                val input = contentResolver.openInputStream(uri)
                val bytes = input?.readBytes()
                input?.close()
                if (bytes == null) {
                    saveToFirestore(null)
                    return
                }
                storage.putBytes(bytes)
                    .continueWithTask { task ->
                        if (!task.isSuccessful) throw task.exception ?: RuntimeException("Upload falhou")
                        storage.downloadUrl
                    }
                    .addOnSuccessListener { downloadUri ->
                        saveToFirestore(downloadUri.toString())
                    }
                    .addOnFailureListener { e ->
                        showSnackbar("Não foi possível enviar a imagem: ${e.message}")
                        saveToFirestore(null)
                    }
            } catch (t: Throwable) {
                showSnackbar("Falha ao ler imagem: ${t.message}")
                saveToFirestore(null)
            }
        }
    }
}

package com.example.indoorar

import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.view.View
import android.widget.*
import androidx.activity.result.contract.ActivityResultContracts
import androidx.core.widget.ImageViewCompat
import com.bumptech.glide.Glide
import com.bumptech.glide.load.engine.DiskCacheStrategy
import com.bumptech.glide.request.RequestListener
import com.bumptech.glide.request.target.Target
import com.bumptech.glide.load.DataSource
import com.bumptech.glide.load.engine.GlideException
import android.graphics.drawable.Drawable
import com.google.android.material.button.MaterialButton
import com.google.android.material.textfield.TextInputEditText
import com.google.firebase.Timestamp
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.storage.FirebaseStorage
import com.google.firebase.storage.StorageMetadata
import com.google.firebase.storage.StorageException

class ActivityCadastrarMapa : BaseActivity() {

    private lateinit var imgPreview: ImageView
    private lateinit var txtHintImagem: TextView
    private lateinit var editNome: TextInputEditText
    private lateinit var editDescricao: TextInputEditText
    private lateinit var dropTipoLocal: AutoCompleteTextView
    private lateinit var editAndar: TextInputEditText
    private lateinit var editHorario: TextInputEditText
    private lateinit var btnSalvar: MaterialButton
    private lateinit var progressSalvar: ProgressBar

    private var selectedImageUri: Uri? = null

    private val pickImage = registerForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
        uri?.let { selected ->
            selectedImageUri = selected
            txtHintImagem.visibility = View.GONE
            // Remover qualquer tint e garantir crop
            ImageViewCompat.setImageTintList(imgPreview, null)
            imgPreview.scaleType = ImageView.ScaleType.CENTER_CROP

            Glide.with(this)
                .load(selected)
                .diskCacheStrategy(DiskCacheStrategy.NONE)
                .skipMemoryCache(true)
                .listener(object : RequestListener<Drawable> {
                    override fun onLoadFailed(
                        e: GlideException?,
                        model: Any?,
                        target: Target<Drawable>?,
                        isFirstResource: Boolean
                    ): Boolean {
                        // Fallback para ImageView caso Glide falhe
                        imgPreview.setImageURI(selected)
                        return true
                    }

                    override fun onResourceReady(
                        resource: Drawable?,
                        model: Any?,
                        target: Target<Drawable>?,
                        dataSource: DataSource?,
                        isFirstResource: Boolean
                    ): Boolean {
                        return false
                    }
                })
                .into(imgPreview)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_cadastrar_mapa)

        // Views
        imgPreview = findViewById(R.id.imgPreview)
        txtHintImagem = findViewById(R.id.txtHintImagem)
        editNome = findViewById(R.id.editNome)
        editDescricao = findViewById(R.id.editDescricao)
        dropTipoLocal = findViewById(R.id.dropTipoLocal)
        editAndar = findViewById(R.id.editAndar)
        editHorario = findViewById(R.id.editHorario)
        btnSalvar = findViewById(R.id.btnSalvar)
        progressSalvar = findViewById(R.id.progressSalvar)

        // Voltar
        findViewById<ImageView>(R.id.btnVoltar).setOnClickListener { onBackPressedDispatcher.onBackPressed() }

        // Dropdown tipos
        val tipos = resources.getStringArray(R.array.tipos_locais)
        val adapter = ArrayAdapter(this, android.R.layout.simple_list_item_1, tipos)
        dropTipoLocal.setAdapter(adapter)

        // Escolher imagem
        findViewById<View>(R.id.cardImagem).setOnClickListener { pickImage.launch("image/*") }
        imgPreview.setOnClickListener { pickImage.launch("image/*") }

        // Salvar
        btnSalvar.setOnClickListener { salvarMapa() }
    }

    private fun setLoading(loading: Boolean) {
        progressSalvar.visibility = if (loading) View.VISIBLE else View.GONE
        btnSalvar.isEnabled = !loading
    }

    private fun salvarMapa() {
        val nome = editNome.text?.toString()?.trim().orEmpty()
        val descricao = editDescricao.text?.toString()?.trim().orEmpty()
        val tipo = dropTipoLocal.text?.toString()?.trim().orEmpty()
        val andar = editAndar.text?.toString()?.trim().orEmpty()
        val horario = editHorario.text?.toString()?.trim().orEmpty()

        // Chips
        val recursos = mutableListOf<String>()
        if (findViewById<CompoundButton>(R.id.chipAcessivel).isChecked) recursos += "Acessível"
        if (findViewById<CompoundButton>(R.id.chipElevador).isChecked) recursos += "Elevador"
        if (findViewById<CompoundButton>(R.id.chipEscadas).isChecked) recursos += "Escadas"
        if (findViewById<CompoundButton>(R.id.chipBanheiros).isChecked) recursos += "Banheiros"
        if (findViewById<CompoundButton>(R.id.chipWifi).isChecked) recursos += "Wi-Fi"
        if (findViewById<CompoundButton>(R.id.chipEstacionamento).isChecked) recursos += "Estacionamento"

        if (nome.isEmpty()) { showSnackbar("Informe o nome do mapa"); return }
        if (descricao.isEmpty()) { showSnackbar("Informe a descrição"); return }
        if (tipo.isEmpty()) { showSnackbar("Selecione o tipo do local"); return }

        val user = FirebaseAuth.getInstance().currentUser
        if (user == null) {
            showSnackbar("Você precisa estar logado para cadastrar um mapa")
            return
        }

        setLoading(true)

        fun returnToCaller(mapId: String) {
            val data = Intent().apply { putExtra("MAP_ID", mapId) }
            setResult(RESULT_OK, data)
            finish()
        }

        fun saveToFirestore(imageUrl: String?) {
            val dados = hashMapOf(
                "nome" to nome,
                "descricao" to descricao,
                "tipo" to tipo,
                "andar" to andar,
                "horario" to horario,
                "recursos" to recursos,
                "imagemUrl" to (imageUrl ?: ""),
                // campos compatíveis com fluxo maker
                "criadorUid" to user.uid,
                "nomeAutor" to (user.displayName ?: ""),
                "dataCriacao" to Timestamp.now()
            )
            FirebaseFirestore.getInstance().collection("mapas")
                .add(dados)
                .addOnSuccessListener { docRef ->
                    showSnackbar("Mapa cadastrado com sucesso.")
                    setLoading(false)
                    returnToCaller(docRef.id)
                }
                .addOnFailureListener { e ->
                    showSnackbar("Erro ao salvar: ${e.message}")
                    setLoading(false)
                }
        }

        val uri = selectedImageUri
        if (uri == null) {
            saveToFirestore(null)
        } else {
            val storageRef = FirebaseStorage.getInstance().reference
                .child("map_images/${user.uid}/${System.currentTimeMillis()}.jpg")
            val contentType = contentResolver.getType(uri) ?: "image/jpeg"
            val metadata = StorageMetadata.Builder()
                .setContentType(contentType)
                .build()

            try {
                val input = contentResolver.openInputStream(uri)
                if (input == null) {
                    showSnackbar("Falha ao acessar a imagem selecionada")
                    saveToFirestore(null)
                    return
                }
                val uploadTask = storageRef.putStream(input, metadata)
                uploadTask
                    .addOnSuccessListener {
                        // Upload OK -> tentar obter URL pública
                        storageRef.downloadUrl
                            .addOnSuccessListener { httpsUri ->
                                saveToFirestore(httpsUri.toString())
                            }
                            .addOnFailureListener { _ ->
                                // Upload ok mas não deu para obter downloadUrl -> salvar gs:// como fallback
                                val gsUrl = storageRef.toString()
                                saveToFirestore(gsUrl)
                            }
                    }
                    .addOnFailureListener { e ->
                        val msg = when (e) {
                            is StorageException -> when (e.errorCode) {
                                StorageException.ERROR_NOT_AUTHORIZED -> "Sem permissão para enviar imagem (verifique as regras do Storage)"
                                StorageException.ERROR_RETRY_LIMIT_EXCEEDED -> "Falha de rede ao enviar imagem"
                                else -> e.message
                            }
                            else -> e.message
                        }
                        showSnackbar("Não foi possível enviar a imagem: ${msg ?: "erro desconhecido"}")
                        saveToFirestore(null)
                    }
                    .addOnCompleteListener { try { input.close() } catch (_: Throwable) {} }
            } catch (t: Throwable) {
                showSnackbar("Falha ao ler imagem: ${t.message}")
                saveToFirestore(null)
            }
        }
    }
}

package com.example.indoorar

import android.content.Intent
import android.os.Bundle
import android.view.View
import android.widget.ImageView
import android.widget.ProgressBar
import android.widget.TextView
import androidx.activity.enableEdgeToEdge
import androidx.activity.result.contract.ActivityResultContracts
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.example.indoorar.ui.ActivityEditor
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.firestore.Query

class ActivityHomeMaker : BaseActivity() {

    private lateinit var recyclerRecentes: RecyclerView
    private lateinit var progressRecentes: ProgressBar
    private lateinit var txtEmptyRecentes: TextView
    private lateinit var txtVerMais: TextView
    private val adapterRecentes = RecentesAdapter { mapa ->
        // Ao clicar abre diretamente o mapa em ActivityMap
        val itn = Intent(this, ActivityMap::class.java)
        itn.putExtra("MAP_ID", mapa.id)
        startActivity(itn)
    }

    private val cadastroLauncher = registerForActivityResult(
        ActivityResultContracts.StartActivityForResult()
    ) { result ->
        if (result.resultCode == RESULT_OK) {
            val mapId = result.data?.getStringExtra("MAP_ID")
            if (!mapId.isNullOrBlank()) {
                startActivity(Intent(this, ActivityEditor::class.java).apply {
                    putExtra("MAP_ID", mapId)
                })
            } else {
                showSnackbar("Não foi possível criar o mapa (MAP_ID ausente)")
            }
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContentView(R.layout.activity_home_maker)

        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }

        // Define dinamicamente o texto de boas-vindas com o nome do usuário logado
        val txtBemVindo = findViewById<TextView>(R.id.txtBemVindo)
        val user = FirebaseAuth.getInstance().currentUser
        val nome = user?.let { u ->
            when {
                !u.displayName.isNullOrBlank() -> u.displayName
                !u.email.isNullOrBlank() -> u.email!!.substringBefore("@")
                else -> null
            }
        }
        txtBemVindo.text = buildString {
            append("BEM-VINDO")
            if (!nome.isNullOrBlank()) {
                append(" ")
                append(nome.uppercase())
            }
        }

        // Botões principais
        findViewById<ImageView>(R.id.btnCriarMapa).setOnClickListener {
            cadastroLauncher.launch(Intent(this, ActivityCadastrarMapa::class.java))
        }
        findViewById<ImageView>(R.id.btnMeusMapas).setOnClickListener {
            startActivity(Intent(this, ActivityMeusMapas::class.java))
        }
        findViewById<ImageView>(R.id.btnPerfil).setOnClickListener {
            startActivity(Intent(this, ActivityPerfil::class.java))
        }

        // Views de recentes
        recyclerRecentes = findViewById(R.id.recyclerRecentes)
        progressRecentes = findViewById(R.id.progressRecentes)
        txtEmptyRecentes = findViewById(R.id.txtEmptyRecentes)
        txtVerMais = findViewById(R.id.txtVerMais)

        recyclerRecentes.layoutManager = LinearLayoutManager(this)
        recyclerRecentes.adapter = adapterRecentes

        txtVerMais.setOnClickListener {
            startActivity(Intent(this, ActivityMeusMapas::class.java))
        }

        carregarRecentes()
    }

    private fun carregarRecentes() {
        val uid = FirebaseAuth.getInstance().currentUser?.uid
        if (uid == null) {
            mostrarVazio()
            return
        }
        progressRecentes.visibility = View.VISIBLE
        txtEmptyRecentes.visibility = View.GONE

        val db = FirebaseFirestore.getInstance()
        db.collection("mapas")
            .whereEqualTo("criadorUid", uid)
            .orderBy("dataCriacao", Query.Direction.DESCENDING)
            .limit(5)
            .get()
            .addOnSuccessListener { snap ->
                if (snap.isEmpty) {
                    adapterRecentes.submit(emptyList())
                    mostrarVazio()
                } else {
                    val lista = snap.documents.map { doc ->
                        val autorUid = doc.getString("criadorUid") ?: uid
                        MapaResumo(
                            id = doc.id,
                            nome = doc.getString("nome") ?: "Mapa sem nome",
                            descricao = doc.getString("descricao") ?: "",
                            autorUid = autorUid,
                            autorNome = doc.getString("nomeAutor") ?: nomeAutorCache(autorUid),
                            dataCriacao = doc.getTimestamp("dataCriacao")
                        )
                    }
                    adapterRecentes.submit(lista)
                    verificarEstadoVazio()
                }
            }
            .addOnFailureListener {
                adapterRecentes.submit(emptyList())
                mostrarVazio()
            }
            .addOnCompleteListener {
                progressRecentes.visibility = View.GONE
            }
    }

    private var cacheAutorNome: String? = null
    private fun nomeAutorCache(uid: String): String {
        if (cacheAutorNome != null) return cacheAutorNome!!
        FirebaseFirestore.getInstance().collection("usuarios").document(uid).get()
            .addOnSuccessListener { d ->
                cacheAutorNome = d.getString("nome") ?: uid
                // Poderia notificar adapter se quisermos atualizar nomes posteriormente
            }
        return uid
    }

    private fun verificarEstadoVazio() {
        val vazio = adapterRecentes.itemCount == 0
        txtEmptyRecentes.visibility = if (vazio) View.VISIBLE else View.GONE
    }

    private fun mostrarVazio() {
        progressRecentes.visibility = View.GONE
        txtEmptyRecentes.visibility = View.VISIBLE
    }
}

